 dl_sc_hanuman:"ശ്രീരാമരക്ഷാ സ്തോത്രം, ശ്ലോകം 33",
 dl_sm_murugan:"കന്ദഷഷ്ഠി കവചത്തിന്റെ കാപ്പ്. സ്തോത്രം തന്നെ പറയുന്ന വാക്ക്: ഇതിനെ സ്തുതിക്കുന്നവർക്കും ഹൃദയത്തിൽ വയ്ക്കുന്നവർക്കും നിർമലനായ കന്ദന്റെ കൃപയാൽ ദുഃഖങ്ങൾ അകലും, മനസ്സ് ഉറയ്ക്കും.",
