 dl_sm_vishnu:"शांत रूप, शेषावर शयन करणारे, नाभीत कमळ, देवांचे स्वामी, विश्वाचा आधार, आकाशासारखे विशाल, मेघासारखे सावळे: संसाराचे भय हरणाऱ्या विष्णूंना वंदन.",
