 dl_cr_dates:"તહેવાર અને તિથિની તારીખો",
 dl_cr_dates_s:"દૃક પંચાંગ, નવી દિલ્હી. તમારા સ્થાનિક પંચાંગમાં એક દિવસનો ફરક હોઈ શકે.",
 dl_sm_hanuman:"જે મન જેવા ઝડપી અને પવન જેવા વેગવાન છે, જેમણે ઇન્દ્રિયો જીતી છે, જે બુદ્ધિમાનોમાં શ્રેષ્ઠ છે, પવનપુત્ર, વાનરોના પ્રમુખ, શ્રીરામના દૂત, હું તેમના શરણે જાઉં છું.",
 dl_ss_hanuman:"હનુમાનજી આખો પર્વત ઉપાડીને લાવે છે. લક્ષ્મણજી ઘાયલ હતા, સંજીવની ઓળખી ન શક્યા તો આખો પર્વત જ લઈ આવ્યા.",
 dl_sc_hanuman:"શ્રી રામ રક્ષા સ્તોત્ર, શ્લોક 33",
 dl_sm_murugan:"કંદ ષષ્ઠી કવચમનો પ્રારંભ (કાપ્પુ). આ સ્તોત્રની પોતાની વાણી છે: જે તેની સ્તુતિ કરે અને તેને હૃદયમાં રાખે, નિર્મળ કંદનની કૃપાથી તેમનાં દુઃખ દૂર થાય અને મન સ્થિર થાય.",
 dl_ss_murugan:"મુરુગન પોતાના મોર પર બિરાજે છે, સાથે વલ્લી અને દેવયાની. મોરના પગ નીચે સાપ છે.",
 dl_sc_murugan:"કંદ ષષ્ઠી કવચમ્, કાપ્પુ · દેવરાય સ્વામિગલ",
 dl_sm_ram:"શિવજી પાર્વતીજીને કહે છે: “રામ, રામ, રામ” બોલીને હું મનોરમ રામમાં રમું છું. એક રામનામ સહસ્ર નામ બરાબર છે.",
 dl_ss_ram:"રામ પંચાયતન: સિંહાસન પર રામ-સીતા, સાથે લક્ષ્મણ, ભરત, શત્રુઘ્ન, અને ચરણોમાં હનુમાનજી.",
 dl_sc_ram:"વિષ્ણુ સહસ્રનામ, ઉત્તર ભાગ",
 dl_sm_shiva:"કપૂર જેવા ગૌર, કરુણાના અવતાર, સંસારના સાર, નાગરાજનો હાર પહેરેલા: જે સદા હૃદયકમળમાં વસે છે, તે ભવને ભવાની સહિત નમન.",
 dl_ss_shiva:"શિવજી પહાડોમાં તપસ્વી રૂપે બેઠા છે, પાસે ત્રિશૂળ. ચરણોમાં નંદી, પાસે એક હરણ, અને સામે એક યુવાન શિષ્ય.",
 dl_sc_shiva:"કર્પૂરગૌરં, પરંપરાગત આરતી શ્લોક",
 dl_sm_ganesha:"હે વક્રતુંડ, મહાકાય, કરોડો સૂર્ય જેવા તેજસ્વી દેવ: મારાં બધાં કામ સદા નિર્વિઘ્ન કરો.",
 dl_ss_ganesha:"ગણેશજી રાજછત્ર નીચે સોનાના સિંહાસન પર બેઠા છે, સાથે રિદ્ધિ અને સિદ્ધિ. બંને બાજુ સેવિકાઓ ચામર ઢોળે છે.",
 dl_sc_ganesha:"વક્રતુંડ મહાકાય, પરંપરાગત શ્લોક",
