 dl_sm_radha_krishna:"વસુદેવના પુત્ર, દિવ્ય, કંસ અને ચાણૂરનો નાશ કરનાર, દેવકીના પરમ આનંદ: જગદ્ગુરુ કૃષ્ણને વંદન.",
 dl_ss_radha_krishna:"સૂર્યાસ્ત વખતે નદીકિનારે બેઠાં રાધા કૃષ્ણની વાંસળી સાંભળે છે.",
