 dl_sm_devi:"જે દેવી સર્વ પ્રાણીઓમાં શક્તિરૂપે રહેલાં છે: તેમને નમસ્કાર, તેમને નમસ્કાર, તેમને વારંવાર નમસ્કાર.",
