 dl_ss_lakshmi:"લક્ષ્મીજી શાંત સરોવરમાં ગુલાબી કમળ પર ઊભાં છે, હાથમાં કમળ. પાછળ એક હાથી હાર ઊંચો કરે છે, અને પાણીમાં હંસ તરે છે.",
