 dl_sm_vishnu:"શાંત રૂપ, શેષનાગ પર શયન કરનાર, નાભિમાં કમળ, દેવોના સ્વામી, જગતના આધાર, આકાશ જેવા વિશાળ, મેઘ જેવા શ્યામ: સંસારનો ભય હરનાર વિષ્ણુને વંદન.",
 dl_ss_vishnu:"વિષ્ણુ ભગવાન ક્ષીરસાગરમાં શેષનાગ પર વિશ્રામ કરે છે. નાભિમાંથી કમળ ઊગ્યું છે, તેના પર બ્રહ્માજી બેઠા છે. પાસે લક્ષ્મીજી અને દેવો છે.",
 dl_sc_vishnu:"શાંતાકારં, પરંપરાગત ધ્યાન શ્લોક",
 dl_sm_saraswati:"જે કુંદ, ચંદ્ર અને હિમ જેવાં ઉજળાં છે, શ્વેત વસ્ત્ર ધારણ કરેલાં, હાથમાં વીણા, શ્વેત કમળ પર બિરાજમાન, બ્રહ્મા, વિષ્ણુ અને શિવથી સદા પૂજિત: બધી જડતા દૂર કરનાર મા સરસ્વતી મારી રક્ષા કરે.",
 dl_ss_saraswati:"મા સરસ્વતી નદીકિનારે એક ખડક પર વીણા અને માળા લઈને બેઠાં છે. પાસે તેમનો મોર ઊભો છે.",
 dl_sc_saraswati:"સરસ્વતી વંદના",
