 dl_sm_murugan:"ਕੰਦ ਸ਼ਸ਼ਠੀ ਕਵਚਮ ਦੀ ਸ਼ੁਰੂਆਤ (ਕਾੱਪੂ)। ਇਹ ਸਤੋਤਰ ਦੀ ਆਪਣੀ ਬਾਣੀ ਹੈ: ਜੋ ਇਸ ਦੀ ਉਸਤਤ ਕਰਦੇ ਹਨ ਤੇ ਇਸਨੂੰ ਦਿਲ ਵਿੱਚ ਰੱਖਦੇ ਹਨ, ਨਿਰਮਲ ਕੰਦਨ ਦੀ ਕਿਰਪਾ ਨਾਲ ਉਨ੍ਹਾਂ ਦੇ ਦੁੱਖ ਦੂਰ ਹੁੰਦੇ ਹਨ ਤੇ ਮਨ ਟਿਕਦਾ ਹੈ।",
